INSERT INTO monster VALUES (625,'Giant Wasp','Giant Wasp',NULL,'Large','Vermin',NULL,'5d8+10 (32 hp)','+1','20 ft. (4 squares), fly 60 ft. (good)','14 (-1 size, +1 Dex, +4 natural), touch 10, flat-footed 13','+3','+11','Sting +6 melee (1d3+6 plus poison)','Sting +6 melee (1d3+6 plus poison)','10 ft.','5 ft.','Poison','Darkvision 60 ft., vermin traits','Fort +6, Ref +2, Will +2','Str 18, Dex 12, Con 14, Int -, Wis 13, Cha 11','Spot +9, Survival +1*',NULL,'-',NULL,'Temperate forests','Solitary, swarm (2-5), or nest (11-20)','3',NULL,NULL,'6-8 HD (Large); 9-15 HD (Huge)','-','Poison (Ex)','Giant wasp; CR 3; Large vermin; HD 5d8+10; hp 32; Init +1; Spd 20 ft. (4 squares), fly 60 ft. (good); AC 14 (-1 size, +1 dex, +4 natural), touch 10, flat-footed 13; Base Atk +3; Grp +11; Atk +6 melee (1d3+6 plus poison, sting); Full Atk +6 melee (1d3+6 plus poison, sting); Space/Reach 10 ft./5 ft.; SA Poison; SQ Darkvision 60 ft., vermin traits; AL N; SV Fort +6, Ref +2, Will +2; Str 18, Dex 12, Con 14, Int -, Wis 13, Cha 11\n\nSkills and Feats: Spot +9, Survival +1*; -','\n      <div topic=\"Giant Wasp\" level=\"2\"><p><h2>Giant Wasp</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Giant Wasp</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Vermin<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>5d8+10 (32 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares), fly 60 ft. (good)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>14 (-1 size, +1 Dex, +4 natural), touch 10, flat-footed 13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+3/+11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Sting +6 melee (1d3+6 plus poison)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Sting +6 melee (1d3+6 plus poison)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Poison<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., vermin traits<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +6, Ref +2, Will +2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 18, Dex 12, Con 14, Int -, Wis 13, Cha 11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Spot +9, Survival +1*<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate forests<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, swarm (2-5), or nest (11-20)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>6-8 HD (Large); 9-15 HD (Huge)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>Giant wasps attack when hungry or threatened, stinging their prey to death. They take dead or incapacitated opponents back to their lairs as food for their unhatched young.</p><div topic=\"Poison\" level=\"8\"><p><b>Poison (Ex):</b> Injury, Fortitude DC 14, initial and secondary damage 1d6 Dex. The save DC is Constitution-based.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Giant wasps have a +8 racial bonus on Spot checks. *They also have a +4 racial bonus on Survival checks to orient themselves.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersVermin');
INSERT INTO monster VALUES (626,'Monstrous Centipede','Monstrous Centipede, Tiny',NULL,'Tiny','Vermin',NULL,'1/4 d8 (1 hp)','+2','20 ft. (4 squares), climb 20 ft.','14 (+2 size, +2 Dex), touch 14, flat-footed 12','+0','-13','Bite +4 melee (1d3-5 plus poison)','Bite +4 melee (1d3-5 plus poison)','2-1/2 ft.','0 ft.','Poison','Darkvision 60 ft., vermin traits','Fort +2, Ref +2, Will +0','Str 1, Dex 15, Con 10, Int -, Wis 10, Cha 2','Climb +10, Hide +18, Spot +4','Weapon Finesse',NULL,NULL,'Underground','Colony (8-16)','1/8',NULL,NULL,'-','-','Poison (Ex)','Tiny monstrous centipede; CR 1/8; Tiny vermin; HD 1/4 d8; hp 1; Init +2; Spd 20 ft. (4 squares), climb 20 ft.; AC 14 (+2 size, +2 dex), touch 14, flat-footed 12; Base Atk +0; Grp -13; Atk +4 melee (1d3-5 plus poison, bite); Full Atk +4 melee (1d3-5 plus poison, bite); Space/Reach 2-1/2 ft./0 ft.; SA Poison; SQ Darkvision 60 ft., vermin traits; AL N; SV Fort +2, Ref +2, Will +0; Str 1, Dex 15, Con 10, Int -, Wis 10, Cha 2\n\nSkills and Feats: Climb +10, Hide +18, Spot +4; Weapon Finesse','\n      <div topic=\"Monstrous Centipede\" level=\"2\"><p><h2>Monstrous Centipede</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Monstrous Centipede, Tiny</b><br/></td>\n\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Tiny Vermin<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1/4 d8 (1 hp)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+2<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares), climb 20 ft.<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>14 (+2 size, +2 Dex), touch 14, flat-footed 12<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+0/-13<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +4 melee (1d3-5 plus poison)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +4 melee (1d3-5 plus poison)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>2-1/2 ft./0 ft.<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Poison<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., vermin traits<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +2, Ref +2, Will +0<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 1, Dex 15, Con 10, Int -, Wis 10, Cha 2<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +10, Hide +18, Spot +4<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Weapon Finesse <sup>B</sup><br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Underground<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Colony (8-16)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1/8<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>-<br/></td>\n\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n\n\n</tr>\n</table><p/><p/><p>Monstrous centipedes tend to attack anything that resembles food, biting with their jaws and injecting their poison.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td><b>Size</b><br/></td> <td><b>Fort DC</b><br/></td>\n<td><b>Damage</b><br/></td>\n<td><b>Size</b><br/></td>\n<td><b>Fort DC</b><br/></td>\n<td><b>Damage</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Tiny<br/></td>\n<td>10<br/></td>\n<td>1 Dex<br/></td>\n<td>Huge<br/></td>\n<td>14<br/></td>\n<td>1d6 Dex<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Small<br/></td>\n<td>10<br/></td>\n<td>1d2 Dex<br/></td>\n<td>Gargantuan<br/></td>\n<td>17<br/></td>\n<td>1d8 Dex<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Medium<br/></td>\n<td>10<br/></td>\n<td>1d3 Dex<br/></td>\n<td>Colossal<br/></td>\n<td>23<br/></td>\n<td>2d6 Dex<br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Large<br/></td>\n<td>11<br/></td>\n<td>1d4 Dex<br/></td>\n<td/>\n<td/>\n<td/>\n\n</tr>\n</table><div topic=\"Poison\" level=\"8\"><p><b>Poison (Ex):</b> A monstrous centipede has a poisonous bite. The details vary by the centipede\'s size, as shown on the table above. The save DCs are Constitution-based. The indicated damage is both initial and secondary damage.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Monstrous centipedes have a +4 racial bonus on Spot checks, and a +8 racial bonus on Climb and Hide checks. They can use either their Strength or Dexterity modifier for Climb checks, whichever is higher. Monstrous scorpions can take 10 on Climb checks, even if threatened or distracted.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersVermin');
